def fibonacci(n):
    memo = {0: 0, 1: 1}

    def helper(k):
        if k in memo:
            return memo[k]
        memo[k] = helper(k - 1) + helper(k - 2)
        return memo[k]

    if n < 0:
        raise ValueError("Input must be non-negative")
    return helper(n)
